import sys, json
d = json.load(sys.stdin)
turns = d.get("messages", [])
calls = [t for t in turns if t.get("type") == "tool_call"]
out = [{"header":{"route":"c_asst"}, "messages":calls}]
def tool_name_of(c):
    # The LlmCell stores the OpenAI function object as a JSON STRING in the
    # tool_call turn's `text` ({"name":...,"arguments":...}). Extract the
    # function name and surrogate it to the routing label 'a'/'b'.
    try:
        fn = json.loads(c.get("text", "{}"))
    except Exception:
        fn = {}
    name = fn.get("name", "")
    # non-{a,b} names collapse to a non-matching sentinel so a misroute fails
    # loudly; valid because the mock emits exactly {a,b}
    return name if name in ("a", "b") else "unknown"
for c in calls:
    out.append({"header":{"route":"tool","tool_call_id":c.get("id",""),"tool_name":tool_name_of(c)}, "messages":[c]})
sys.stdout.write(json.dumps(out))
